import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 21 章 岗位路线图：不同岗位如何把我用深","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第四篇 岗位与行业落地/第 21 章 岗位路线图：不同岗位如何把我用深.md","filePath":"bluebook/第四篇 岗位与行业落地/第 21 章 岗位路线图：不同岗位如何把我用深.md"}'),o={name:"bluebook/第四篇 岗位与行业落地/第 21 章 岗位路线图：不同岗位如何把我用深.md"};function n(s,t,l,h,i,p){return d(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="第-21-章-岗位路线图-不同岗位如何把我用深" tabindex="-1">第 21 章 岗位路线图：不同岗位如何把我用深 <a class="header-anchor" href="#第-21-章-岗位路线图-不同岗位如何把我用深" aria-label="Permalink to &quot;第 21 章 岗位路线图：不同岗位如何把我用深&quot;">​</a></h1><h2 id="_21-1-为什么分岗位" tabindex="-1">21.1 为什么分岗位 <a class="header-anchor" href="#_21-1-为什么分岗位" aria-label="Permalink to &quot;21.1 为什么分岗位&quot;">​</a></h2><p>同样的我，在不同岗位手里，价值完全不同。区别不在能力，在<strong>岗位的典型任务流</strong>。本章给出 6 个典型岗位的用法路线。</p><h2 id="_21-2-产品经理" tabindex="-1">21.2 产品经理 <a class="header-anchor" href="#_21-2-产品经理" aria-label="Permalink to &quot;21.2 产品经理&quot;">​</a></h2><p><strong>典型任务：</strong> 需求文档、竞品分析、数据复盘、排期。</p><p><strong>我的用法：</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>怎么做</th></tr></thead><tbody><tr><td>需求文档</td><td>先出大纲（背景/用户/功能/验收）→ 逐节填充 → 你补业务判断</td></tr><tr><td>竞品分析</td><td>提供资料 → 我按维度对比表整理 → 标出差异与机会</td></tr><tr><td>数据复盘</td><td>给数据 → 我出结论+图表 → 你补业务解释</td></tr><tr><td>会议纪要</td><td>发我记录 → 我提炼决议、待办、责任人</td></tr></tbody></table><p><strong>路线图：</strong> 第 2 章（需求模板）→ 第 9 章（文档）→ 第 12 章（数据）→ 第 17 章（沉淀需求文档 Skill）。</p><h2 id="_21-3-开发者" tabindex="-1">21.3 开发者 <a class="header-anchor" href="#_21-3-开发者" aria-label="Permalink to &quot;21.3 开发者&quot;">​</a></h2><p><strong>典型任务：</strong> 写代码、改 bug、代码评审、技术文档。</p><p><strong>我的用法：</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>怎么做</th></tr></thead><tbody><tr><td>写代码</td><td>给需求+约束 → 我写+自测 → 你 review diff</td></tr><tr><td>改 bug</td><td>给报错 → 我定位+修复+验证 → 你确认根因</td></tr><tr><td>代码评审</td><td>我按规范检查 → 出问题清单 → 你决策</td></tr><tr><td>技术文档</td><td>我读代码 → 生成架构/接口文档 → 你校对</td></tr></tbody></table><p><strong>路线图：</strong> 第 10 章（代码）→ 第 3 章（工具）→ 第 17 章（封装 commit/review Skill）→ 第 19 章（CI 自动化）。</p><h2 id="_21-4-运营" tabindex="-1">21.4 运营 <a class="header-anchor" href="#_21-4-运营" aria-label="Permalink to &quot;21.4 运营&quot;">​</a></h2><p><strong>典型任务：</strong> 数据日报、活动复盘、内容产出、用户分析。</p><p><strong>我的用法：</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>怎么做</th></tr></thead><tbody><tr><td>日报/周报</td><td>给数据源 → 我套模板生成 → 你补充业务解读</td></tr><tr><td>活动复盘</td><td>给活动数据 → 我算 ROI/漏斗 → 出结论与建议</td></tr><tr><td>内容产出</td><td>给主题+素材 → 我出多版文案 → 你选方向</td></tr><tr><td>用户分析</td><td>给用户数据 → 我分群+找规律 → 你定策略</td></tr></tbody></table><p><strong>路线图：</strong> 第 12 章（数据）→ 第 14 章（信息流）→ 第 15 章（自动化日报）→ 第 17 章（复盘模板 Skill）。</p><h2 id="_21-5-设计师" tabindex="-1">21.5 设计师 <a class="header-anchor" href="#_21-5-设计师" aria-label="Permalink to &quot;21.5 设计师&quot;">​</a></h2><p><strong>典型任务：</strong> 设计规范、标注、素材整理、方案说明。</p><p><strong>我的用法：</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>怎么做</th></tr></thead><tbody><tr><td>设计规范</td><td>我给结构 → 我整理成文档 → 你填充视觉细节</td></tr><tr><td>方案说明</td><td>给设计稿描述 → 我写设计说明 → 你校对</td></tr><tr><td>素材整理</td><td>给素材目录 → 我分类+命名+建索引</td></tr><tr><td>走查清单</td><td>我按可访问性/一致性出清单 → 你逐项核对</td></tr></tbody></table><p><strong>路线图：</strong> 第 9 章（文档）→ 第 11 章（文件整理）→ 第 17 章（走查清单 Skill）。</p><h2 id="_21-6-市场-销售" tabindex="-1">21.6 市场/销售 <a class="header-anchor" href="#_21-6-市场-销售" aria-label="Permalink to &quot;21.6 市场/销售&quot;">​</a></h2><p><strong>典型任务：</strong> 文案、资料包、客户信息整理、简报。</p><p><strong>我的用法：</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>怎么做</th></tr></thead><tbody><tr><td>营销文案</td><td>给产品卖点+受众 → 我出多版本 → 你挑方向</td></tr><tr><td>资料包</td><td>给素材 → 我组织成结构（手册/一页纸）</td></tr><tr><td>客户整理</td><td>给原始数据 → 我清洗+分群+标注跟进状态</td></tr><tr><td>竞品简报</td><td>给资料 → 我对比+出要点</td></tr></tbody></table><p><strong>路线图：</strong> 第 14 章（资讯）→ 第 9 章（文档）→ 第 11 章（整理）→ 第 17 章（文案模板 Skill）。</p><h2 id="_21-7-管理者" tabindex="-1">21.7 管理者 <a class="header-anchor" href="#_21-7-管理者" aria-label="Permalink to &quot;21.7 管理者&quot;">​</a></h2><p><strong>典型任务：</strong> 汇总、汇报、任务分配、复盘。</p><p><strong>我的用法：</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>怎么做</th></tr></thead><tbody><tr><td>汇总汇报</td><td>收齐各组材料 → 我合并提炼 → 你补充判断</td></tr><tr><td>任务分配</td><td>给目标 → 我拆任务 → 你拍板分工</td></tr><tr><td>团队复盘</td><td>给复盘材料 → 我归类问题+沉淀改进项</td></tr><tr><td>团队 AI 化</td><td>按第 18 章设计团队系统，沉淀共享 Skill</td></tr></tbody></table><p><strong>路线图：</strong> 第 16 章（团队协作）→ 第 18 章（系统设计）→ 第 17 章（团队共享 Skill）。</p><h2 id="_21-8-通用落地步骤" tabindex="-1">21.8 通用落地步骤 <a class="header-anchor" href="#_21-8-通用落地步骤" aria-label="Permalink to &quot;21.8 通用落地步骤&quot;">​</a></h2><p>无论哪个岗位，都用同一套流程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 列出你每周重复的 5 件事</span></span>
<span class="line"><span>2. 挑 2 件交给我做成流程（第 2、4 章）</span></span>
<span class="line"><span>3. 跑顺后沉淀为 Skill（第 17 章）</span></span>
<span class="line"><span>4. 每周省下的时间 → 投入到判断型工作</span></span></code></pre></div><h2 id="_21-9-练习" tabindex="-1">21.9 练习 <a class="header-anchor" href="#_21-9-练习" aria-label="Permalink to &quot;21.9 练习&quot;">​</a></h2><ol><li>对照你的岗位，列出每周最重复的 5 件事；</li><li>标出其中 2 件&quot;步骤固定、可交给 AI&quot;的；</li><li>按四要素模板，把第一件交给我跑通。</li></ol><blockquote><p>小结：岗位落地的公式 = <strong>典型任务 + 复用模板 + 持续沉淀</strong>。价值不是&quot;会用 AI&quot;，而是&quot;岗位效率真的变了&quot;。</p></blockquote>`,39)])])}const g=a(o,[["render",n]]);export{_ as __pageData,g as default};
